def _next_pow2(n, cap):
    p = 1
    while p < n and p < cap:
        p *= 2
    return p


@functools.lru_cache(maxsize=1024)
def _repair_ok(H, Ho, plh, U):
    # The breakpoint-chain jump-group path is valid when the group spans at
    # most one slice boundary (U <= Ho) and at most two sh-wraps in any
    # U-consecutive-row window (then the kw1/kw2 slots provably cover all
    # wraps: the first wrap at or after h0 is at h0 + ((P-h0) mod H), later
    # ones at +H, and post-boundary ones at kb + P, kb + P + H).
    if U > Ho:
        return False
    P = plh % H
    start = P if P > 0 else H
    pos = list(range(start, Ho, H))
    rows = sorted([s * Ho + p for s in range(3) for p in pos])
    j0 = 0
    mx = 0
    for i, r in enumerate(rows):
        while rows[j0] <= r - U:
            j0 += 1
        mx = max(mx, i - j0 + 1)
    return mx <= 2


def _seg_consts(plw, W, Wo):
    ll = max(plw, 0)
    am = ll
    lm = min(plw + W, Wo) - am
    sm = am - plw
    ar = min(plw + W, Wo)
    lr = Wo - ar
    sr = ar - plw - W
    sl = W - plw
    pw = ll + lr
    return ll, am, lm, sm, ar, lr, sr, sl, pw


def _pad_circular(x: torch.Tensor, pad):
    logger.debug("GEMS_ENFLAME _PAD_CIRCULAR")

    ndim = x.dim()
    if len(pad) % 2 != 0:
        raise ValueError("padding length must be even")
    npad = len(pad) // 2
    if npad < 1 or npad > 3:
        raise ValueError(
            "flag_gems _pad_circular supports padding the last 1, 2 or 3 dimensions"
        )
    if ndim <= npad:
        raise ValueError("input must have at least one non-padded (batch) dimension")

    x = x.contiguous()
    in_shape = list(x.shape)
    out_shape = list(in_shape)
    pad_left = [0] * ndim
    for i in range(npad):
        d = ndim - 1 - i
        pl = int(pad[2 * i])
        pr = int(pad[2 * i + 1])
        new_size = in_shape[d] + pl + pr
        if new_size <= 0:
            raise ValueError(
                "negative padding removed the whole dimension "
                f"{d}: input {in_shape[d]} pad ({pl}, {pr})"
            )
        # circular padding wraps at most once; guard the invariant the kernel relies on
        if pl > in_shape[d] or pr > in_shape[d]:
            raise ValueError("Padding value causes wrapping around more than once.")
        out_shape[d] = new_size
        pad_left[d] = pl

    out = torch.empty(out_shape, dtype=x.dtype, device=x.device)
    total = 1
    for s in out_shape:
        total *= s
    if total == 0:
        return out

    W = in_shape[ndim - 1]
    H = in_shape[ndim - 2] if npad >= 2 else 1
    D = in_shape[ndim - 3] if npad >= 3 else 1
    Wo = out_shape[ndim - 1]
    Ho = out_shape[ndim - 2] if npad >= 2 else 1
    Do = out_shape[ndim - 3] if npad >= 3 else 1
    plw = pad_left[ndim - 1]
    plh = pad_left[ndim - 2] if npad >= 2 else 0
    pld = pad_left[ndim - 3] if npad >= 3 else 0
    B = 1
    for s in in_shape[:-npad]:
        B *= s
    R = B * Do * Ho

    def _launch():
        if W > 8192:
            # very wide rows: chunked general path
            lL = max(plw, 0)
            aR = min(plw + W, Wo)
            lR = Wo - aR
            FPAD = max(16, _next_pow2(max(lL, lR), 1024))
            grid = (min(48, R),)
            _pad_circular_wide_kernel[grid](
                x,
                out,
                R,
                W,
                Wo,
                plw,
                Ho,
                H,
                Do,
                D,
                plh,
                pld,
                NPAD=npad,
                BLOCK=8192,
                FPAD=FPAD,
                num_warps=4,
            )
            return

        if npad == 1:
            if W >= 768 or W < 64:
                U, nw = 8, (4 if W >= 768 else 2)
            else:
                U, nw = 20, 2
            chains_ok = True
        else:
            if W >= 768:
                U, nw = 8, 4
            elif W >= 512:
                U, nw = 20, 2
            elif W >= 64:
                U, nw = 32, 2
            else:
                U, nw = 20, 2
            chains_ok = _repair_ok(H, Ho, plh, U)
            if not chains_ok:
                if _repair_ok(H, Ho, plh, 16):
                    U, chains_ok = 16, True
                elif _repair_ok(H, Ho, plh, 8):
                    U, chains_ok = 8, True
        if not chains_ok:
            # breakpoint invariants do not hold for this geometry: fall back
            # to the v1 kernel whose per-row slow path is fully general.
            if W >= 2048:
                U2 = 4
            elif W >= 768 or W < 64:
                U2 = 8
            else:
                U2 = 20
            grid = (min(48, max(1, R // U2)),)
            _pad_circular_rowseg_kernel[grid](
                x,
                out,
                R,
                W,
                Wo,
                plw,
                Ho,
                H,
                Do,
                D,
                plh,
                pld,
                NPAD=npad,
                BLOCK=_next_pow2(W, 8192),
                GBLOCK=1024,
                U=U2,
                num_warps=2,
            )
            return

        BLOCK = _next_pow2(W, 8192)
        LL, AM, LM, SM, AR, LR, SR, SL, PW = _seg_consts(plw, W, Wo)
        P = plh % H
        sh0 = (0 - plh) % H
        shl = (Ho - 1 - plh) % H
        DH_B = (H + sh0 - shl - 1) * W
        sd0 = (0 - pld) % D
        sdl = (Do - 1 - pld) % D
        C1 = (sh0 - shl - 1) * W
        C2B = (D + sd0 - sdl) * H * W + C1
        grid = (min(48, max(1, R // U)),)
        kern = (
            _pad_circular_rowseg_v4_U8
            if U == 8
            else (
                _pad_circular_rowseg_v4_U16
                if U == 16
                else (
                    _pad_circular_rowseg_v4_U20
                    if U == 20
                    else _pad_circular_rowseg_v4_U32
                )
            )
        )
        kern[grid](
            x,
            out,
            R,
            W=W,
            Wo=Wo,
            Ho=Ho,
            H=H,
            Do=Do,
            D=D,
            plw=plw,
            plh=plh,
            pld=pld,
            LL=LL,
            AM=AM,
            LM=LM,
            SM=SM,
            AR=AR,
            PW=PW,
            SL=SL,
            SR=SR,
            P=P,
            DH_B=DH_B,
            C1=C1,
            C2B=C2B,
            NPAD=npad,
            BLOCK=BLOCK,
            GBLOCK=1024,
            num_warps=nw,
        )

    # cold compiles hit the documented node-level toolchain segfault family
    # (P02): a fresh-compile subprocess can die with SIGSEGV before producing
    # a cache entry; retrying the launch re-enters compilation and succeeds
    # (atan2_/sinh precedent). Zero cost on the warm path.
    for attempt in range(3):
        try:
            with torch_device_fn.device(x.device):
                _launch()
            break
        except Exception:
            if attempt == 2:
                raise
    return out
